#!/usr/bin/env python3
"""
The "What to do now" cards, written from the open guide ("Довідник виживання" 2.3, CC BY-SA 4.0).
Each step follows the guide's own words, shortened for a stressed reader; "why" is the second
level. Every card names the guide sections it comes from. None is reviewed by a specialist yet.

    python3 scripts/content/cards.py   -> content/src/main/assets/cards.json
"""
import json, os

CHECKED = "2026-10-30"
SRC = "«Довідник виживання» 2.3 (CC BY-SA 4.0)"

def card(id, title, guide, steps, call=""):
    return {"id": id, "title": title, "guide": guide, "call": call,
            "source": f"{SRC}, п. {', '.join(guide)}", "checkedOn": CHECKED, "reviewedBy": "",
            "steps": [{"action": a, "why": w} for a, w in steps]}

